import { validateAccount } from './solution';
import type { AccountRecord, ValidationIssue } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function fields(issues: readonly ValidationIssue[]): string {
  return issues.map(issue => issue.field).join(',');
}
function duplicateCount(issues: readonly ValidationIssue[]): number {
  return issues.filter(issue => issue.message === 'Email is already in use').length;
}

const accounts = [
  { id: 'a', email: 'Taken@Example.com' },
  { id: 'b', email: 'other@example.org' },
] as AccountRecord[];

const validCreate = { displayName: ' Alice ', secret: ' value ', email: 'alice@example.com' };
equal(validateAccount('CREATE', validCreate, accounts).length, 0, 'valid CREATE');
const missing = validateAccount('CREATE', {}, accounts);
equal(fields(missing), 'displayName,secret,email', 'CREATE validation order');
equal(missing.length, 3, 'one required issue per missing field');

const malformedCreate = validateAccount('CREATE', {
  displayName: 12,
  secret: '   ',
  email: 'a@@example.com',
}, accounts);
equal(fields(malformedCreate), 'displayName,secret,email', 'malformed CREATE field order');
equal(malformedCreate.length, 3, 'at most one format issue per field');

for (const email of ['@example.com', 'a@', 'a@example', 'a@.example', 'a@example.', 'a@exam..ple']) {
  const issues = validateAccount('CREATE', { displayName: 'A', secret: 'S', email }, []);
  equal(fields(issues), 'email', `invalid email ${email}`);
  equal(issues.length, 1, `one issue for invalid email ${email}`);
}

const createDuplicate = validateAccount('CREATE', {
  displayName: 'A', secret: 'S', email: '  taken@example.COM  ',
}, accounts);
equal(duplicateCount(createDuplicate), 1, 'CREATE duplicate is trimmed and case-insensitive');
equal(createDuplicate.length, 1, 'well-formed duplicate has one uniqueness issue');

const emptyUpdateA = validateAccount('UPDATE', {}, accounts);
const emptyUpdateB = validateAccount('UPDATE', {}, accounts);
equal(emptyUpdateA.length, 0, 'empty UPDATE valid');
assert(emptyUpdateA !== emptyUpdateB, 'fresh issue array returned');

equal(fields(validateAccount('UPDATE', {
  accessLevel: undefined,
  email: 'bad',
  displayName: ' ',
  unknown: false,
}, accounts)), 'displayName,email,accessLevel', 'UPDATE validates own properties in fixed order');

const inherited = Object.create({ email: 'bad' }) as Record<string, unknown>;
equal(validateAccount('UPDATE', inherited, accounts).length, 0, 'inherited properties ignored');

equal(validateAccount('UPDATE', { email: 'TAKEN@example.com' }, accounts, 'a').length, 0, 'current account excluded');
equal(duplicateCount(validateAccount('UPDATE', { email: 'taken@example.com' }, accounts)), 1, 'omitted currentId excludes none');
equal(duplicateCount(validateAccount('UPDATE', { email: 'taken@example.com' }, accounts, 'b')), 1, 'different currentId remains duplicate');

const reversed = [...accounts].reverse();
const forwardIssues = validateAccount('CREATE', { displayName: 'A', secret: 'S', email: 'taken@example.com' }, accounts);
const reverseIssues = validateAccount('CREATE', { displayName: 'A', secret: 'S', email: 'taken@example.com' }, reversed);
equal(JSON.stringify(forwardIssues), JSON.stringify(reverseIssues), 'account order does not affect output');
equal(accounts[0].email, 'Taken@Example.com', 'accounts not mutated');
equal(validCreate.email, 'alice@example.com', 'body not mutated');

